{
  "groups": [
    {
      "group_id": "low_rate_fixed_vulnerable",
      "rule": "rate_type == 'fixed' and origination_year <= 2021.0 and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who secured low fixed rates before the recent rate hikes face the most severe payment shocks at renewal and are highly sensitive to retention offers."
    },
    {
      "group_id": "high_debt_young_family",
      "rule": "n_children >= 2 and adjusted_family_net_income_cad < 75000 and mortgage_balance_cad > 400000",
      "rationale": "Households with multiple children and limited net income have restricted cash flow and represent a segment at high risk of payment stress."
    },
    {
      "group_id": "prime_insured_shoppers",
      "rule": "insured_flag == True and credit_score_band == '720_plus' and channel == 'digital'",
      "rationale": "These highly creditworthy, insured borrowers possess maximum market mobility and are prone to shopping for the best rate via digital channels."
    },
    {
      "group_id": "variable_rate_stretched",
      "rule": "rate_type == 'variable' and credit_utilization_pct > 40.0 and payment_structure == 'adjustable_payment'",
      "rationale": "Variable rate borrowers with adjustable payments feel interest rate hikes immediately in their monthly budget and are already showing signs of higher credit reliance."
    },
    {
      "group_id": "self_employed_complex",
      "rule": "employment_status == 'self_employed' and mortgage_balance_cad > 450000 and has_savings == False",
      "rationale": "Self-employed borrowers without liquid savings lack a safety net and may face difficulty refinancing elsewhere if their income documentation is perceived as inconsistent."
    },
    {
      "group_id": "stable_equity_rich",
      "rule": "credit_score_band == '720_plus' and property_value_cad > 700000 and has_investments == True",
      "rationale": "Wealthy, stable homeowners are likely to prioritize long-term relationship benefits and ease of renewal over chasing the lowest available mortgage rate."
    },
    {
      "group_id": "credit_constrained_captive",
      "rule": "credit_score_band in ['600_659', 'below_600'] and insured_flag == False",
      "rationale": "Borrowers with lower credit scores who are not insured face significantly limited refinancing options, making them essentially captive to their existing lender."
    },
    {
      "group_id": "late_cycle_high_rate",
      "rule": "origination_year >= 2022.0 and mortgage_rate_pct > 5.0",
      "rationale": "Borrowers who entered the market during the recent high-rate environment have less accumulated equity and are sensitive to any further market fluctuations."
    }
  ]
}
